draw(circle((0,0), 2));
draw(circle((6,0), 2));
draw((-2,0)--(2,0));
draw((0,-2)--(0,2));
path p=(0,0)--(0,2);
draw(shift(6,0)*p);
draw(shift(6,0)*rotate(120)*p);
draw(shift(6,0)*rotate(240)*p);
label(scale(0.6)*"1", (-1,1));
